with filtered as (select id, customer_id, account_type, balance, opened_date, status, round(balance, 0) as balance_rounded from accounts where opened_date > date '2023-07-11') select case when balance_rounded >= 87 then 'HIGH' else 'LOW' end as balance_rounded_tier, approx_percentile(balance_rounded, array(0.25, 0.5, 0.75)) as balance_rounded_quartiles, count(distinct customer_id) as distinct_customer_ids, sum(case when status = 'FROZEN' then balance_rounded else 0 end) as frozen_balance_rounded from filtered group by 1;
